WITH flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, device, SUM(CASE WHEN country = 'TH' THEN is_new_burst ELSE 0 END) AS th_is_new_burst, COUNT(*) AS cnt, MAX(started_at) AS ended_at FROM sessionized GROUP BY DATE_TRUNC('MONTH', started_at), device;
